def wolfram_query_with_assumptions(api_key_id, query, parent_query_id, assumptions, client_metadata=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0278000" if __import__("os").path.isdir("./environment_mix/0278000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _utcnow():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _day_utc(dt):
        return dt.strftime("%Y-%m-%d")

    def _ulid(prefix):
        ms = int(datetime.datetime.utcnow().timestamp() * 1000)

        def _enc_time(v):
            out = []
            for _ in range(10):
                out.append(crock[v % 32])
                v //= 32
            return "".join(reversed(out))

        rand = "".join(random.choice(crock) for _ in range(16))
        return prefix + _enc_time(ms) + rand

    def _log_usage(usage_events, api_key_id_row, query_id_row, event_type, billable, cost_units):
        now = _iso(_utcnow())
        ev = {
            "id": _ulid("wa_use_"),
            "api_key_id": api_key_id_row,
            "query_id": query_id_row,
            "event_type": event_type,
            "billable": bool(billable),
            "cost_units": int(cost_units),
            "occurred_at": now,
            "created_at": now,
            "updated_at": now,
        }
        usage_events.append(ev)
        return ev

    def _count_rate_window(usage_events, key_id, now_dt, window_sec=60):
        start = now_dt - datetime.timedelta(seconds=window_sec)
        c = 0
        for ev in usage_events:
            if not isinstance(ev, dict):
                continue
            if ev.get("api_key_id") != key_id:
                continue
            if ev.get("event_type") != "request_accepted":
                continue
            dt = _parse_iso(ev.get("occurred_at"))
            if dt is None:
                continue
            if dt >= start and dt <= now_dt:
                c += 1
        return c

    def _count_daily_success_units(usage_events, key_id, day_str):
        units = 0
        for ev in usage_events:
            if not isinstance(ev, dict):
                continue
            if ev.get("api_key_id") != key_id:
                continue
            if ev.get("event_type") != "request_succeeded":
                continue
            if not ev.get("billable", False):
                continue
            dt = _parse_iso(ev.get("occurred_at"))
            if dt is None:
                continue
            if _day_utc(dt) == day_str:
                try:
                    units += int(ev.get("cost_units", 0) or 0)
                except Exception:
                    units += 0
        return units

    def _find_key(api_keys, key_param):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_param:
                return k
        return None

    def _find_query(query_sessions, qid):
        for q in query_sessions:
            if isinstance(q, dict) and q.get("id") == qid:
                return q
        return None

    def _find_response(wolfram_responses, qid):
        for r in wolfram_responses:
            if isinstance(r, dict) and r.get("query_id") == qid:
                return r
        return None

    # ---- Validate inputs ----
    if not isinstance(api_key_id, str) or not re.match(r"^wa_key_[0-9A-HJKMNP-TV-Z]{16,}$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must match ^wa_key_[0-9A-HJKMNP-TV-Z]{16,}$", field="api_key_id")
    if not isinstance(parent_query_id, str) or not re.match(r"^wa_qry_[0-9A-HJKMNP-TV-Z]{16,}$", parent_query_id):
        return _err("VALIDATION_ERROR", "parent_query_id must match ^wa_qry_[0-9A-HJKMNP-TV-Z]{16,}$", field="parent_query_id")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string", field="query")
    if not isinstance(assumptions, list) or len(assumptions) < 1:
        return _err("VALIDATION_ERROR", "assumptions must be a non-empty array", field="assumptions")
    for i, a in enumerate(assumptions):
        if not isinstance(a, dict):
            return _err("VALIDATION_ERROR", "each assumption must be an object", field="assumptions", index=i)
        if "assumption_key" not in a or "candidate" not in a:
            return _err("VALIDATION_ERROR", "each assumption must include assumption_key and candidate", field="assumptions", index=i)
        if not isinstance(a.get("assumption_key"), str) or not a.get("assumption_key").strip():
            return _err("VALIDATION_ERROR", "assumption_key must be a non-empty string", field="assumptions", index=i, subfield="assumption_key")
        if not isinstance(a.get("candidate"), dict):
            return _err("VALIDATION_ERROR", "candidate must be an object", field="assumptions", index=i, subfield="candidate")
    if client_metadata is not None and not isinstance(client_metadata, dict):
        return _err("VALIDATION_ERROR", "client_metadata must be an object", field="client_metadata")

    # ---- Load datastore ----
    api_keys = _load("api_keys.json")
    query_sessions = _load("query_sessions.json")
    query_assumptions_rows = _load("query_assumptions.json")
    wolfram_responses = _load("wolfram_responses.json")
    usage_events = _load("usage_events.json")

    # ---- Authenticate/authorize api key ----
    key = _find_key(api_keys, api_key_id)
    if key is None:
        # No key to charge; no usage event possible.
        return _err("UNAUTHORIZED", "API key not found or not authorized for this operation.", api_key_id=api_key_id)
    if key.get("status") != "active":
        # Business rule: do not create query_sessions when key not active; record failed.
        _log_usage(usage_events, api_key_id, None, "request_failed", False, 0)
        _save("usage_events.json", usage_events)
        return _err("UNAUTHORIZED", "api_keys.status must be 'active' to accept requests", rule="api_keys.status must be active", status=key.get("status"))

    now_dt = _utcnow()
    now_iso = _iso(now_dt)

    # ---- Enforce rate limit (accepted requests) ----
    try:
        rate_limit = int(key.get("rate_limit_per_minute", 0) or 0)
    except Exception:
        rate_limit = 0
    if rate_limit > 0:
        accepted_last_min = _count_rate_window(usage_events, api_key_id, now_dt, 60)
        if accepted_last_min >= rate_limit:
            _log_usage(usage_events, api_key_id, None, "request_rate_limited", False, 0)
            _save("usage_events.json", usage_events)
            return _err("RATE_LIMIT", "Rate limit exceeded for this API key.", rule="accepted requests in sliding 60s window must be <= api_keys.rate_limit_per_minute", rate_limit_per_minute=rate_limit)

    # ---- Enforce daily quota (successful billable units) ----
    try:
        daily_quota = int(key.get("quota_daily_requests", 0) or 0)
    except Exception:
        daily_quota = 0
    if daily_quota >= 0:
        used_units_today = _count_daily_success_units(usage_events, api_key_id, _day_utc(now_dt))
        if daily_quota == 0 or used_units_today >= daily_quota:
            _log_usage(usage_events, api_key_id, None, "request_quota_exceeded", False, 0)
            _save("usage_events.json", usage_events)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key.", rule="sum of billable request_succeeded.cost_units per UTC day must be <= api_keys.quota_daily_requests", quota_daily_requests=daily_quota, used_today=used_units_today)

    # ---- Validate parent query and assumptions context ----
    parent = _find_query(query_sessions, parent_query_id)
    if parent is None:
        # Parent must exist.
        _log_usage(usage_events, api_key_id, None, "request_failed", False, 0)
        _save("usage_events.json", usage_events)
        return _err("NOT_FOUND", "parent_query_id was not found", field="parent_query_id", parent_query_id=parent_query_id)

    # Must not mutate parent's user_query_text; also assumptions only allowed when ambiguity_detected=true
    if not parent.get("ambiguity_detected", False):
        _log_usage(usage_events, api_key_id, None, "request_failed", False, 0)
        _save("usage_events.json", usage_events)
        return _err("VALIDATION_ERROR", "query_assumptions rows are only allowed for query_sessions where ambiguity_detected=true", rule="query_assumptions only allowed when parent query ambiguity_detected=true", parent_query_id=parent_query_id)

    # Find relevant assumption rows for this parent query; accept even if current status is unselected by transitioning unselected->selected->applied.
    # Also allow providing assumption_key not present in store: that is a missing reference.
    asm_by_key = {}
    for arow in query_assumptions_rows:
        if not isinstance(arow, dict):
            continue
        if arow.get("query_id") == parent_query_id:
            ak = arow.get("assumption_key")
            if isinstance(ak, str):
                asm_by_key[ak] = arow

    for a in assumptions:
        ak = a["assumption_key"]
        if ak not in asm_by_key:
            _log_usage(usage_events, api_key_id, None, "request_failed", False, 0)
            _save("usage_events.json", usage_events)
            return _err("NOT_FOUND", "Assumption key not found for parent query.", rule="assumption_key must exist for parent query", assumption_key=ak, parent_query_id=parent_query_id)

    # ---- Record request accepted (counts for rate limit) ----
    _log_usage(usage_events, api_key_id, None, "request_accepted", False, 0)

    # ---- Create follow-up query session ----
    follow_id = _ulid("wa_qry_")
    follow_session = {
        "id": follow_id,
        "api_key_id": api_key_id,
        "parent_query_id": parent_query_id,
        "tool_name": "wolfram_query_with_assumptions",
        "user_query_text": query,  # from tool boundary (in this implementation)
        "normalized_query_text": query.strip(),
        "client_metadata": client_metadata if isinstance(client_metadata, dict) else None,
        "status": "queued",
        "ambiguity_detected": False,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    query_sessions.append(follow_session)

    # ---- Apply selected assumptions on parent query's query_assumptions rows ----
    # Relaxed transition logic to accept applying from unselected by stepping through selected.
    applied = []
    for a in assumptions:
        ak = a["assumption_key"]
        cand = a["candidate"]
        row = asm_by_key.get(ak)
        if row is None:
            continue
        cur = row.get("status")
        # Allowed transitions: unselected->selected, selected->applied. If already applied, idempotent update candidate.
        if cur == "unselected":
            row["status"] = "selected"
            cur = "selected"
        if cur == "selected":
            row["selected_candidate"] = cand
            row["status"] = "applied"
        elif cur == "applied":
            # idempotent: keep applied, but refresh selected_candidate to reflect request
            row["selected_candidate"] = cand
        else:
            # Unknown status: validation error
            follow_session["status"] = "failed"
            follow_session["error_code"] = "INVALID_ASSUMPTION_STATE"
            follow_session["error_message"] = "Assumption is in an invalid state."
            follow_session["updated_at"] = _iso(_utcnow())
            _log_usage(usage_events, api_key_id, follow_id, "request_failed", False, 0)
            key["updated_at"] = _iso(_utcnow())
            _save("api_keys.json", api_keys)
            _save("query_sessions.json", query_sessions)
            _save("query_assumptions.json", query_assumptions_rows)
            _save("usage_events.json", usage_events)
            return _err("INVALID_TRANSITION", "Assumption cannot transition to 'applied' from its current status.", rule="query_assumptions.status must allow transition to 'applied' per lifecycle graph (relaxed via unselected->selected->applied)", status=cur, assumption_key=ak)

        row["updated_at"] = _iso(_utcnow())
        applied.append({"assumption_key": ak, "selected_candidate": row.get("selected_candidate")})

    # ---- Simulate upstream call/response persistence (offline) ----
    # Persist a wolfram_responses row for follow-up query. Preserve uniqueness(query_id) by overwrite if exists.
    follow_upstream_request = {
        "query": query.strip(),
        "parent_query_id": parent_query_id,
        "assumptions": [{"assumption_key": a["assumption_key"], "candidate": a["candidate"]} for a in assumptions],
    }
    # Minimal deterministic response object
    upstream_response = {
        "query": query.strip(),
        "assumptions_applied": [{"assumption_key": x["assumption_key"]} for x in assumptions],
        "status": "success",
    }
    rsp = _find_response(wolfram_responses, follow_id)
    if rsp is None:
        rsp = {
            "id": _ulid("wa_rsp_"),
            "query_id": follow_id,
            "upstream_request": follow_upstream_request,
            "upstream_response": upstream_response,
            "result_text": None,
            "pods": None,
            "assumptions": None,
            "upstream_status": "success",
            "http_status_code": 200,
            "created_at": _iso(_utcnow()),
            "updated_at": _iso(_utcnow()),
        }
        wolfram_responses.append(rsp)
    else:
        rsp["upstream_request"] = follow_upstream_request
        rsp["upstream_response"] = upstream_response
        rsp["upstream_status"] = "success"
        rsp["http_status_code"] = 200
        rsp["updated_at"] = _iso(_utcnow())

    # ---- Transition follow-up session to succeeded (queued->running->succeeded) ----
    # Enforce lifecycle graph steps.
    follow_session["status"] = "running"
    follow_session["updated_at"] = _iso(_utcnow())
    # pretend some latency
    latency_ms = int((time.time() - t0) * 1000)
    if latency_ms < 0:
        latency_ms = 0
    follow_session["status"] = "succeeded"
    follow_session["latency_ms"] = latency_ms
    follow_session["updated_at"] = _iso(_utcnow())

    # ---- Record succeeded usage event (billable) ----
    _log_usage(usage_events, api_key_id, follow_id, "request_succeeded", True, 1)

    # ---- Update api_key last_used_at on successful request ----
    key["last_used_at"] = _iso(_utcnow())
    key["updated_at"] = _iso(_utcnow())

    # ---- Persist ----
    _save("api_keys.json", api_keys)
    _save("query_sessions.json", query_sessions)
    _save("query_assumptions.json", query_assumptions_rows)
    _save("wolfram_responses.json", wolfram_responses)
    _save("usage_events.json", usage_events)

    # ---- Return envelope with stored session, response, and applied assumptions ----
    return {
        "query_session": follow_session,
        "wolfram_response": rsp,
        "applied_assumptions": applied,
        "parent_query_id": parent_query_id,
        "latency_ms": latency_ms,
    }

def wolfram_list_query_sessions(api_key_id, status=None, parent_query_id=None, created_after=None, created_before=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0278000" if __import__("os").path.isdir("./environment_mix/0278000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    crockford = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        rnd = "".join(random.choice(crockford) for _ in range(20))
        return f"{prefix}{rnd}"
    def _find_by_id(rows, _id):
        for r in rows:
            if isinstance(r, dict) and r.get("id") == _id:
                return r
        return None

    # validate
    if not isinstance(api_key_id, str) or not re.match(r"^wa_key_[0-9A-HJKMNP-TV-Z]{16,}$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id is invalid.", field="api_key_id")
    valid_status = {"queued","running","needs_assumptions","succeeded","failed","cancelled"}
    if status is not None and (not isinstance(status, str) or status not in valid_status):
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if parent_query_id is not None:
        if not isinstance(parent_query_id, str) or not re.match(r"^wa_qry_[0-9A-HJKMNP-TV-Z]{16,}$", parent_query_id):
            return _err("VALIDATION_ERROR", "parent_query_id is invalid.", field="parent_query_id")
    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string.", field=field)
        try:
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string.", field=field)
    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if order is None:
        order = "created_at_desc"
    if order not in ("created_at_desc", "created_at_asc"):
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")

    api_keys = _load("api_keys.json")
    sessions = _load("query_sessions.json")
    usage = _load("usage_events.json")

    key = _find_by_id(api_keys, api_key_id)
    if not key:
        # log failed access
        usage.append({
            "id": _ulid_like("wa_use_"),
            "api_key_id": api_key_id,
            "query_id": None,
            "event_type": "request_failed",
            "billable": False,
            "cost_units": 0,
            "occurred_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key not found.")
    if key.get("status") != "active":
        usage.append({
            "id": _ulid_like("wa_use_"),
            "api_key_id": api_key_id,
            "query_id": None,
            "event_type": "request_failed",
            "billable": False,
            "cost_units": 0,
            "occurred_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("usage_events.json", usage)
        return _err("UNAUTHORIZED", "API key is not active.", status=key.get("status"))

    # record a non-billable accepted event for reads? Schema doesn't define read events; use request_accepted as observable dynamics without charging.
    usage.append({
        "id": _ulid_like("wa_use_"),
        "api_key_id": api_key_id,
        "query_id": None,
        "event_type": "request_accepted",
        "billable": False,
        "cost_units": 0,
        "occurred_at": now,
        "created_at": now,
        "updated_at": now,
    })
    _save("usage_events.json", usage)

    # filter sessions by api_key_id (visibility)
    filtered = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if s.get("api_key_id") != api_key_id:
            continue
        if status is not None and s.get("status") != status:
            continue
        if parent_query_id is not None and s.get("parent_query_id") != parent_query_id:
            continue
        try:
            sdt = datetime.datetime.fromisoformat(s.get("created_at"))
            if sdt.tzinfo is None:
                sdt = sdt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            # if bad data, skip
            continue
        if ca is not None and not (sdt > ca):
            continue
        if cb is not None and not (sdt < cb):
            continue
        filtered.append(s)

    # sort
    def _created_at_dt(s):
        try:
            dt = datetime.datetime.fromisoformat(s.get("created_at"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)

    reverse = (order == "created_at_desc")
    filtered.sort(key=_created_at_dt, reverse=reverse)

    # cursor: encode as "created_at|id" of last item returned; resume after that (stable)
    start = 0
    if cursor:
        # find index after cursor
        parts = cursor.split("|", 1)
        if len(parts) != 2:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        c_created_at, c_id = parts
        found = False
        for i, s in enumerate(filtered):
            if s.get("id") == c_id and s.get("created_at") == c_created_at:
                start = i + 1
                found = True
                break
        if not found:
            # treat as invalid cursor
            return _err("VALIDATION_ERROR", "Cursor does not match results.", field="cursor")

    page = filtered[start:start+limit]
    has_more = start + limit < len(filtered)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = f"{last.get('created_at')}|{last.get('id')}"

    return {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "order": order,
        },
    }

def wolfram_get_query_session(api_key_id, query_id, include_response=None, include_assumptions=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0278000" if __import__("os").path.isdir("./environment_mix/0278000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    crockford = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        rnd = "".join(random.choice(crockford) for _ in range(20))
        return f"{prefix}{rnd}"
    def _find_by_id(rows, _id):
        for r in rows:
            if isinstance(r, dict) and r.get("id") == _id:
                return r
        return None

    if include_response is None:
        include_response = False
    if include_assumptions is None:
        include_assumptions = False

    # validate
    if not isinstance(api_key_id, str) or not re.match(r"^wa_key_[0-9A-HJKMNP-TV-Z]{16,}$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id is invalid.", field="api_key_id")
