            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    crock = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _utcnow():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid(prefix):
        ms = int(datetime.datetime.utcnow().timestamp() * 1000)

        def _enc_time(v):
            out = []
            for _ in range(10):
                out.append(crock[v % 32])
                v //= 32
            return "".join(reversed(out))

        rand = "".join(random.choice(crock) for _ in range(16))
        return prefix + _enc_time(ms) + rand

    def _log_usage(usage_events, api_key_id_row, query_id_row, event_type, billable, cost_units):
        now = _iso(_utcnow())
        ev = {
            "id": _ulid("wa_use_"),
            "api_key_id": api_key_id_row,
            "query_id": query_id_row,
            "event_type": event_type,
            "billable": bool(billable),
            "cost_units": int(cost_units),
            "occurred_at": now,
            "created_at": now,
            "updated_at": now,
        }
        usage_events.append(ev)
        return ev

    def _find_key(api_keys, key_param):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_param:
                return k
        return None

    def _find_query(query_sessions, qid):
        for q in query_sessions:
            if isinstance(q, dict) and q.get("id") == qid:
                return q
        return None

    # ---- Validate inputs ----
    if not isinstance(api_key_id, str) or not re.match(r"^wa_key_[0-9A-HJKMNP-TV-Z]{16,}$", api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id must match ^wa_key_[0-9A-HJKMNP-TV-Z]{16,}$", field="api_key_id")
    if not isinstance(query_id, str) or not re.match(r"^wa_qry_[0-9A-HJKMNP-TV-Z]{16,}$", query_id):
        return _err("VALIDATION_ERROR", "query_id must match ^wa_qry_[0-9A-HJKMNP-TV-Z]{16,}$", field="query_id")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string", field="reason")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason must be <= 500 characters", field="reason", maxLength=500)

    # ---- Load datastore ----
    api_keys = _load("api_keys.json")
    query_sessions = _load("query_sessions.json")
    usage_events = _load("usage_events.json")

    # ---- Authenticate api key (must exist; status not required for cancellation) ----
    key = _find_key(api_keys, api_key_id)
    if key is None:
        return _err("UNAUTHORIZED", "API key not found or not authorized for this operation.", api_key_id=api_key_id)

    # ---- Find query session ----
    sess = _find_query(query_sessions, query_id)
    if sess is None:
        return _err("NOT_FOUND", "Query session not found.", query_id=query_id)

    # Must belong to this api_key_id
    if sess.get("api_key_id") != api_key_id:
        return _err("UNAUTHORIZED", "Query session is not associated with the provided api_key_id.", rule="query_sessions.api_key_id must match", query_id=query_id)

    cur = sess.get("status")
    terminal = {"succeeded", "failed", "cancelled"}
    if cur in terminal:
        # Important: reflect actual business rule; do not misclassify as invalid transition elsewhere.
        return _err("CONFLICT", "Cancellation is not allowed because the query session is already in a terminal state.", rule="query_sessions.status is terminal and cannot transition to 'cancelled' per lifecycle graph", status=cur)

    # Enforce lifecycle transitions: queued/running/needs_assumptions -> cancelled allowed
    allowed_from = {"queued", "running", "needs_assumptions"}
    if cur not in allowed_from:
        return _err("INVALID_TRANSITION", "Query session cannot transition to 'cancelled' from its current status.", rule="query_sessions.status must allow transition to 'cancelled' per lifecycle graph", status=cur)

    # ---- Mutate ----
    now_iso = _iso(_utcnow())
    sess["status"] = "cancelled"
    sess["updated_at"] = now_iso
    sess["latency_ms"] = sess.get("latency_ms", None)
    # Store cancellation detail in error fields (observed pattern in datastore examples)
    sess["error_code"] = "CLIENT_CANCELLED"
    if reason is not None and reason.strip():
        sess["error_message"] = reason.strip()
    else:
        sess["error_message"] = "Request cancelled by client before completion."

    # Record usage event for cancellation as failed (non-billable)
    _log_usage(usage_events, api_key_id, query_id, "request_failed", False, 0)

    # Update api_key timestamps
    key["updated_at"] = now_iso

    # Persist
    _save("api_keys.json", api_keys)
    _save("query_sessions.json", query_sessions)
    _save("usage_events.json", usage_events)

    latency_ms = int((time.time() - t0) * 1000)
    if latency_ms < 0:
        latency_ms = 0

    return {"query_session": sess, "latency_ms": latency_ms}

def wolfram_get_wolfram_response(api_key_id, query_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0278000" if __import__("os").path.isdir("./environment_mix/0278000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _isoday(dt):
        return dt.strftime("%Y-%m-%d")

    def _valid_key_id(s):
        return isinstance(s, str) and re.match(r"^wa_key_[0-9A-HJKMNP-TV-Z]{16,}$", s) is not None

    def _valid_query_id(s):
        return isinstance(s, str) and re.match(r"^wa_qry_[0-9A-HJKMNP-TV-Z]{16,}$", s) is not None

    def _make_event_id():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(datetime.datetime.utcnow().timestamp() * 1000)
        def _enc_time(v):
            out = []
            for _ in range(10):
                out.append(alphabet[v % 32])
                v //= 32
            return "".join(reversed(out))
        import random
        rand = "".join(alphabet[random.randrange(32)] for _ in range(16))
        return "wa_evt_" + _enc_time(ts) + rand

    def _log_usage(usage_events, api_key_id_row, query_id_row, event_type, billable, cost_units):
        now = _utcnow_iso()
        ev = {
            "id": _make_event_id(),
            "api_key_id": api_key_id_row,
            "query_id": query_id_row,
            "event_type": event_type,
            "billable": bool(billable),
            "cost_units": int(cost_units),
            "occurred_at": now,
            "created_at": now,
            "updated_at": now,
        }
        usage_events.append(ev)
        _save("usage_events.json", usage_events)

    def _rate_limit_exceeded(usage_events, key_id, per_min):
        try:
            per_min = int(per_min)
        except Exception:
            return False
        if per_min <= 0:
            return False
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for ev in usage_events:
            if ev.get("api_key_id") != key_id:
                continue
            if ev.get("event_type") != "request_accepted":
                continue
            dt = _parse_iso(ev.get("occurred_at"))
            if not dt:
                continue
            if dt >= window_start and dt <= now:
                cnt += 1
        return cnt >= per_min

    def _quota_exceeded(usage_events, key_id, quota_daily):
        try:
            quota_daily = int(quota_daily)
        except Exception:
            return False
        if quota_daily < 0:
            quota_daily = 0
        now = datetime.datetime.utcnow()
        day = _isoday(now)
        used = 0
        for ev in usage_events:
            if ev.get("api_key_id") != key_id:
                continue
            if ev.get("event_type") != "request_succeeded":
                continue
            if not ev.get("billable", False):
                continue
            dt = _parse_iso(ev.get("occurred_at"))
            if not dt:
                continue
            if _isoday(dt) == day:
                try:
                    used += int(ev.get("cost_units", 0))
                except Exception:
                    pass
        return used >= quota_daily

    if not _valid_key_id(api_key_id):
        return _err("VALIDATION_ERROR", "api_key_id is malformed")
    if not _valid_query_id(query_id):
        return _err("VALIDATION_ERROR", "query_id is malformed")

    api_keys = _load("api_keys.json")
    key = next((k for k in api_keys if k.get("id") == api_key_id), None)
    usage_events = _load("usage_events.json")

    if not key:
        return _err("UNAUTHORIZED", "API key is unknown")
    if key.get("status") != "active":
        _log_usage(usage_events, api_key_id, query_id, "request_failed", False, 0)
        return _err("UNAUTHORIZED", "API key is not active", status=key.get("status"))
    if _rate_limit_exceeded(usage_events, api_key_id, key.get("rate_limit_per_minute")):
        _log_usage(usage_events, api_key_id, query_id, "request_rate_limited", False, 0)
        return _err("RATE_LIMIT", "Rate limit exceeded")
    if _quota_exceeded(usage_events, api_key_id, key.get("quota_daily_requests")):
        _log_usage(usage_events, api_key_id, query_id, "request_quota_exceeded", False, 0)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    _log_usage(usage_events, api_key_id, query_id, "request_accepted", False, 0)

    query_sessions = _load("query_sessions.json")
    session = next((q for q in query_sessions if q.get("id") == query_id and q.get("api_key_id") == api_key_id), None)
    if not session:
        usage_events = _load("usage_events.json")
        _log_usage(usage_events, api_key_id, query_id, "request_failed", False, 0)
        return _err("NOT_FOUND", "Query session not found for this API key")

    wolfram_responses = _load("wolfram_responses.json")
    resp = next((r for r in wolfram_responses if r.get("query_id") == query_id), None)
    if not resp:
        usage_events = _load("usage_events.json")
        _log_usage(usage_events, api_key_id, query_id, "request_failed", False, 0)
        return _err("NOT_FOUND", "No stored Wolfram response for this query session")

    usage_events = _load("usage_events.json")
    _log_usage(usage_events, api_key_id, query_id, "request_succeeded", True, 1)

    now_iso = _utcnow_iso()
    key["last_used_at"] = now_iso
    key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {"object": "wolfram_response", "data": resp, "latency_ms": latency_ms}

