    if key.get("status") != "active":
        _log_usage(usage_events, api_key_id, None, "request_failed", False, 0)
        return _err("UNAUTHORIZED", "API key is not active", status=key.get("status"))

    # Record dynamics (accepted)
    _log_usage(usage_events, api_key_id, None, "request_accepted", False, 0)

    snapshot = None
    if include_usage:
        now = datetime.datetime.utcnow()
        day = _isoday(now)

        # daily billable succeeded cost units
        daily_used = 0
        for ev in usage_events:
            if ev.get("api_key_id") != api_key_id:
                continue
            if ev.get("event_type") != "request_succeeded":
                continue
            if not ev.get("billable", False):
                continue
            dt = _parse_iso(ev.get("occurred_at"))
            if not dt:
                continue
            if _isoday(dt) == day:
                try:
                    daily_used += int(ev.get("cost_units", 0))
                except Exception:
                    pass

        # sliding 60s accepted count
        window_start = now - datetime.timedelta(seconds=60)
        accepted_60s = 0
        for ev in usage_events:
            if ev.get("api_key_id") != api_key_id:
                continue
            if ev.get("event_type") != "request_accepted":
                continue
            dt = _parse_iso(ev.get("occurred_at"))
            if not dt:
                continue
            if dt >= window_start and dt <= now:
                accepted_60s += 1

        try:
            quota = int(key.get("quota_daily_requests", 0))
        except Exception:
            quota = 0
        try:
            rate = int(key.get("rate_limit_per_minute", 0))
        except Exception:
            rate = 0

        snapshot = {
            "daily": {
                "utc_day": day,
                "quota_daily_requests": quota,
                "used_cost_units": daily_used,
                "remaining_cost_units": max(0, quota - daily_used),
            },
            "rate_limit": {
                "window_seconds": 60,
                "rate_limit_per_minute": rate,
                "accepted_requests_in_window": accepted_60s,
                "remaining_in_window": max(0, rate - accepted_60s) if rate > 0 else None,
            },
        }

    # Mark succeeded for whoami call (counts as billable "successful request" in this simplified ledger)
    usage_events = _load("usage_events.json")
    _log_usage(usage_events, api_key_id, None, "request_succeeded", True, 1)

    now_iso = _utcnow_iso()
    key["last_used_at"] = now_iso
    key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    out = {
        "object": "api_key",
        "data": {
            "id": key.get("id"),
            "label": key.get("label"),
            "status": key.get("status"),
            "quota_daily_requests": key.get("quota_daily_requests"),
            "rate_limit_per_minute": key.get("rate_limit_per_minute"),
            "last_used_at": key.get("last_used_at"),
            "created_at": key.get("created_at"),
            "updated_at": key.get("updated_at"),
        },
        "latency_ms": latency_ms,
    }
    if include_usage:
        out["usage"] = snapshot
    return out
